import {properties} from './model.mjs';
import {EVENT_TYPES,today,eventStatus,eventCounts,seedEvents,restoreEvents,selectEvents,summarizeEvents,saveEvent,saveAttendee,checkIn,safePhotoUrl} from './events-model.mjs';

export function createEventsWorkspace({esc,btn,chip,heading,panel,metric,icon,filters,render,navigate,openDialog,closeDialog,toast}){
 const KEY='mf-hub-onsite-events-v1';
 let data=seedEvents(),storage=true,month=today().slice(0,7),filter={type:'all',from:'',to:'',search:''},activeTab='calendar',detailTab='overview';
 try{data=restoreEvents(JSON.parse(localStorage.getItem(KEY)||'null'));}catch{storage=false;}
 const pName=id=>properties.find(p=>p.id===id)?.name||id;
 const scopeName=e=>e.propertyIds.length===properties.length?'Portfolio-wide':e.propertyIds.map(pName).join(', ');
 const dateLabel=date=>new Date(date+'T12:00:00Z').toLocaleDateString('en-CA',{weekday:'short',month:'short',day:'numeric',year:'numeric',timeZone:'UTC'});
 const eventById=id=>data.events.find(e=>e.id===id);
 function commit(change){const previous=JSON.stringify(data);try{const result=change();localStorage.setItem(KEY,JSON.stringify(data));storage=true;return result;}catch(error){data=JSON.parse(previous);throw Error(error.name==='QuotaExceededError'?'Browser storage is full. Remove an event photo before saving another.':error.message);}}
 function snapshotEvents(id){return selectEvents(data.events,id?{property:id}:filters);}
 function selection(tab=activeTab){const f={...filter};if(tab==='planned')f.status='Planned';if(tab==='past')f.status='Past';if(tab==='calendar'){f.from=f.from&&f.from>month+'-01'?f.from:month+'-01';const end=new Date(Number(month.slice(0,4)),Number(month.slice(5,7)),0).getDate();f.to=f.to&&f.to<month+'-'+end?f.to:month+'-'+end;}return selectEvents(data.events,filters,f);}
 function eventButton(e,label=e.title){return btn(esc(label),'event-open',`data-id="${esc(e.id)}"`,'ghost');}
 function statusChip(e){const status=eventStatus(e);return chip(status,status==='Planned'?'info':status==='Past'?'good':'warn');}
 function eventCard(e){const c=eventCounts(e);return `<article class="event-card"><div class="event-card-top">${chip(e.type)}${statusChip(e)}</div><button class="event-title" data-action="event-open" data-id="${esc(e.id)}">${esc(e.title)}</button><p>${esc(scopeName(e))}</p><div class="event-card-date">${icon('calendar',16)} ${dateLabel(e.date)} · ${esc(e.start)}–${esc(e.end)}</div><p>${esc(e.location)}</p><div class="event-card-bottom"><span><strong>${c.rsvps}</strong> RSVPs · <strong>${c.attended}</strong> attended</span>${eventButton(e,'View event →')}</div></article>`;}
 function controls(){return `<div class="filters event-filters">${[['pmc','Management company'],['city','City']].map(([key,label])=>`<div class="filter"><label for="event-scope-${key}">${label}</label><select id="event-scope-${key}" data-event-scope="${key}"><option value="all">All ${key==='pmc'?'companies':'cities'}</option>${[...new Set(properties.map(p=>p[key]))].map(v=>`<option ${filters[key]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></div>`).join('')}<div class="filter property"><label for="event-scope-property">Property</label><select id="event-scope-property" data-event-scope="property"><option value="all">Whole portfolio</option>${properties.map(p=>`<option value="${p.id}" ${filters.property===p.id?'selected':''}>${p.name}</option>`).join('')}</select></div><div class="filter"><label for="event-type">Event type</label><select id="event-type" data-event-filter="type"><option value="all">All event types</option>${EVENT_TYPES.map(t=>`<option ${filter.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="filter"><label for="event-from">From</label><input type="date" id="event-from" data-event-filter="from" value="${filter.from}"></div><div class="filter"><label for="event-to">To</label><input type="date" id="event-to" data-event-filter="to" value="${filter.to}"></div>${btn('Clear filters','event-clear','','secondary')}</div>`;}
 function calendar(events){const [year,mo]=month.split('-').map(Number),first=(new Date(year,mo-1,1).getDay()+6)%7,days=new Date(year,mo,0).getDate();const label=new Date(year,mo-1,1).toLocaleDateString('en-CA',{month:'long',year:'numeric'});return panel(label,'Event times are shown in Eastern Time. Select any event to open its details.',`<div class="event-month-bar">${btn('← Previous','event-month','data-step="-1"','secondary small')}<div><label class="small" for="event-month">Jump to month</label><input id="event-month" type="month" value="${month}" aria-label="Calendar month"></div>${btn('Today','event-today','','secondary small')}${btn('Next →','event-month','data-step="1"','secondary small')}</div><div class="event-calendar" role="region" aria-label="${label} event calendar"><div class="event-weekdays">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<span>${d}</span>`).join('')}</div><div class="event-days">${Array.from({length:Math.ceil((days+first)/7)*7},(_,i)=>{const day=i-first+1;if(day<1||day>days)return '<div class="event-day outside" aria-hidden="true"></div>';const key=month+'-'+String(day).padStart(2,'0'),items=events.filter(e=>e.date===key);return `<div class="event-day ${key===today()?'today':''}"><span class="event-day-number">${day}</span>${items.map(e=>`<button class="event-calendar-item ${e.cancelled?'cancelled':''}" data-action="event-open" data-id="${esc(e.id)}"><span>${esc(e.start)}</span><strong>${esc(e.title)}</strong><small>${esc(scopeName(e))}</small></button>`).join('')}</div>`;}).join('')}</div></div><div class="event-mobile-agenda">${events.length?events.map(eventCard).join(''):'<p class="event-empty">No events this month. Browse another month or plan a new event.</p>'}</div>${events.length?'':'<p class="event-desktop-empty event-empty">No events match this month and your filters.</p>'}`);}
 function photoTile(e,p,i){const url=safePhotoUrl(p.url);return `<button class="event-photo-tile" data-action="event-photo" data-id="${esc(e.id)}" data-index="${i}" aria-label="View photo: ${esc(p.caption)}">${url?`<img src="${esc(url)}" alt="${esc(p.caption)}" loading="lazy" referrerpolicy="no-referrer">`:'<span>Photo unavailable</span>'}<span><strong>${esc(e.title)}</strong><small>${esc(p.caption)}${p.illustrative?' · Illustrative':''}</small></span></button>`;}
 function workspace(tab){activeTab=['calendar','planned','past','photos'].includes(tab)?tab:'calendar';const events=selection(),s=summarizeEvents(events),list=activeTab==='past'?[...events].reverse():events;return heading('Bring your communities together.','Resident events, RSVPs and memories across your portfolio.',btn('+ Plan event','event-new'),'Events')+controls()+`<div class="metrics event-kpis">${metric('Events in view',s.total,'Current filters','calendar')}${metric('Planned events',s.planned,'Today and upcoming','clock')}${metric('Confirmed RSVPs',s.rsvps,'Upcoming events · includes guests','people')}${metric('Past attendance',s.attended,'Recorded check-ins · includes guests','check')}</div><nav class="tabs" aria-label="Event views">${[['calendar','Event calendar'],['planned','Planned events'],['past','Past events'],['photos','Event pictures']].map(([id,label])=>`<button class="tab ${activeTab===id?'active':''}" data-action="navigate" data-route="events/${id}" ${activeTab===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav><div class="event-toolbar"><form id="event-search-form"><label class="sr-only" for="event-search">Search events</label><input id="event-search" name="search" placeholder="Search events, venue or organizer…" value="${esc(filter.search)}"><button type="submit" class="btn secondary">Search</button></form>${btn(icon('download',14)+' Export events','event-export','','secondary')}</div>${activeTab==='calendar'?calendar(events):activeTab==='photos'?panel('Event pictures',`${s.photos} photos across the selected events. Sample venue photos are marked illustrative.`,`<div class="event-photos">${events.flatMap(e=>e.photos.map((p,i)=>photoTile(e,p,i))).join('')||'<p class="event-empty">No event pictures yet. Open an event to add photos.</p>'}</div>`):`<div class="event-card-grid">${list.map(eventCard).join('')||'<div class="panel event-empty">No matching events. Clear filters or plan a new event.</div>'}</div>`}<p class="event-storage">Fictional event and resident records. ${storage?'Changes and uploaded photos are saved in this browser only.':'Browser storage is unavailable; saving may not work.'} No invitations or notifications are sent.</p>`;}
 function summary(id,compact=false){const events=snapshotEvents(id),s=summarizeEvents(events),next=events.find(e=>eventStatus(e)==='Planned');return `<section class="property-section event-property-summary"><div class="property-section-heading"><h3>Events</h3>${btn('View events →','event-scope',`data-property="${id||'all'}"`,'ghost small')}</div><div class="event-summary-stats"><span><strong>${s.planned}</strong> planned</span><span><strong>${s.past}</strong> past</span><span><strong>${s.photos}</strong> photos</span></div>${next?`<div class="event-next"><small>Next event · ${dateLabel(next.date)}</small>${eventButton(next)}<small>${eventCounts(next).rsvps} confirmed RSVPs · ${esc(next.location)}</small></div>`:'<p class="small">No upcoming events planned.</p>'}${compact?'':`<div class="event-summary-stats"><span>${s.rsvps} upcoming RSVPs</span><span>${s.attended} past check-ins</span></div>${events.filter(e=>eventStatus(e)==='Past').slice(-2).reverse().map(e=>`<div class="row"><span>${eventButton(e)}<small>${dateLabel(e.date)} · ${eventCounts(e).attended} attended · ${e.photos.length} photos</small></span>${chip('Past','good')}</div>`).join('')}`}</section>`;}
 function details(id,tab='overview'){const e=eventById(id);if(!e)return;detailTab=tab;const c=eventCounts(e);openDialog(esc(e.title),`${esc(scopeName(e))} · ${dateLabel(e.date)} · ${e.start}–${e.end} ET`,`${statusChip(e)} ${chip(e.type)}<nav class="tabs event-detail-tabs" aria-label="Event details">${[['overview','Overview'],['attendees','RSVPs & attendees'],['photos','Pictures']].map(([t,label])=>btn(label,'event-detail-tab',`data-id="${e.id}" data-tab="${t}"`,t===tab?'':'secondary')).join('')}</nav>${tab==='overview'?`<p class="event-description">${esc(e.description||'No description added.')}</p><div class="detail-grid"><div><small>Venue</small><strong>${esc(e.location)}</strong></div><div><small>Organizer</small><strong>${esc(e.owner)}</strong></div><div><small>Capacity</small><strong>${e.capacity} people</strong></div><div><small>Availability</small><strong>${Math.max(0,e.capacity-c.rsvps)} places remaining</strong></div></div><div class="dialog-metrics"><div><small>Confirmed RSVPs</small><strong>${c.rsvps}</strong></div><div><small>Attended</small><strong>${c.attended}</strong></div><div><small>Waitlist</small><strong>${c.waitlist}</strong></div></div><p class="small">Counts include guests. Check-in records are manually maintained in this demo.</p><div class="dialog-actions">${btn('Edit event','event-edit',`data-id="${e.id}"`,'secondary')}${btn(e.cancelled?'Restore event':'Cancel event','event-cancel',`data-id="${e.id}"`,'secondary')}${btn('Manage RSVPs','event-detail-tab',`data-id="${e.id}" data-tab="attendees"`)}</div>`:tab==='attendees'?`<div class="event-attendee-head"><p class="small">${c.rsvps} confirmed · ${c.attended} attended · ${c.waitlist} waitlisted<br>Counts include guests; check-in applies to the resident and their guests.</p>${btn('+ Add RSVP','event-attendee-new',`data-id="${e.id}" ${e.cancelled?'disabled':''}`)}</div>${e.attendees.map(a=>`<article class="event-attendee"><div><strong>${esc(a.name)}</strong><small>${esc(pName(a.property))} · ${a.unit?'Unit '+esc(a.unit):'No unit'} · ${a.guests} guests</small>${chip(a.response,a.response==='Going'?'good':'')} ${a.checkedIn?chip('Checked in','info'):''}</div><div>${btn('Edit RSVP','event-attendee-edit',`data-id="${e.id}" data-person="${a.id}" ${e.cancelled?'disabled':''}`,'secondary small')}${btn(a.checkedIn?'Undo check-in':'Check in','event-checkin',`data-id="${e.id}" data-person="${a.id}" ${e.cancelled||e.date>today()||a.response!=='Going'?'disabled':''}`,'secondary small')}</div></article>`).join('')||'<p class="event-empty">No RSVPs yet.</p>'}${e.date>today()?'<p class="small">Attendance opens on the event date.</p>':''}`:`<div class="event-photos">${e.photos.map((p,i)=>photoTile(e,p,i)).join('')||'<p class="event-empty">Add your first event picture.</p>'}</div><form id="event-photo-form" data-id="${e.id}"><div class="field"><label for="event-photo-file">Upload picture</label><input id="event-photo-file" name="file" type="file" accept="image/jpeg,image/png,image/webp"><small>JPEG, PNG or WebP · up to 1 MB each · up to 8 photos per event.</small></div><div class="field"><label for="event-photo-caption">Caption</label><input id="event-photo-caption" name="caption" maxlength="120" required placeholder="Describe this event moment"></div><p role="alert" class="event-form-error"></p><button class="btn" type="submit">Save picture</button></form>`}<p class="event-storage">Demo only · saved in this browser · no invitations sent.</p>`);}
 function eventForm(id){const e=eventById(id)||{title:'',propertyIds:filters.property==='all'?properties.map(p=>p.id):[filters.property],date:today(),start:'18:00',end:'20:00',type:EVENT_TYPES[0],location:'',owner:properties.find(p=>p.id===filters.property)?.owner||properties[0].owner,description:'',capacity:50};const fields=[['title','Event name','text',100],['date','Date','date'],['start','Start time (ET)','time'],['end','End time (ET)','time'],['location','Venue / location','text',150],['owner','Organizer','text',80],['capacity','Capacity (including guests)','number']];openDialog(id?'Edit event':'Plan a resident event','Create one event for a property or the whole portfolio.',`<form id="event-form" data-id="${id||''}"><div class="event-form-grid">${fields.map(([name,label,type,max])=>`<div class="field"><label for="event-${name}">${label}</label><input id="event-${name}" name="${name}" type="${type}" value="${esc(e[name])}" required ${max?`maxlength="${max}"`:''} ${type==='number'?'min="1" max="10000"':''}></div>`).join('')}<div class="field"><label for="event-kind">Event type</label><select id="event-kind" name="type">${EVENT_TYPES.map(t=>`<option ${e.type===t?'selected':''}>${t}</option>`).join('')}</select></div></div><fieldset class="event-property-picker"><legend>Participating properties</legend>${properties.map(p=>`<label><input type="checkbox" name="propertyIds" value="${p.id}" ${e.propertyIds.includes(p.id)?'checked':''}> ${p.name}</label>`).join('')}<small>Select every property for a portfolio-wide event.</small></fieldset><div class="field"><label for="event-description">Description</label><textarea id="event-description" name="description" maxlength="1500">${esc(e.description)}</textarea></div><p class="event-form-error" role="alert"></p><div class="dialog-actions">${btn('Close','close','','secondary')}<button type="submit" class="btn">Save event</button></div></form>`);}
 function attendeeForm(eventId,personId){const e=eventById(eventId);if(!e)return;const a=e.attendees.find(a=>a.id===personId)||{name:'',unit:'',property:e.propertyIds[0],response:'Going',guests:0};openDialog(personId?'Edit RSVP':'Add resident RSVP',esc(e.title),`<form id="event-attendee-form" data-id="${e.id}" data-person="${personId||''}"><div class="event-form-grid">${[['name','Resident name','text'],['unit','Unit (optional)','text'],['guests','Additional guests','number']].map(([n,l,t])=>`<div class="field"><label for="attendee-${n}">${l}</label><input id="attendee-${n}" name="${n}" type="${t}" value="${esc(a[n])}" ${n!=='unit'?'required':''} ${t==='number'?'min="0" max="10"':'maxlength="80"'}></div>`).join('')}<div class="field"><label for="attendee-property">Property</label><select id="attendee-property" name="property">${e.propertyIds.map(id=>`<option value="${id}" ${a.property===id?'selected':''}>${pName(id)}</option>`).join('')}</select></div><div class="field"><label for="attendee-response">RSVP</label><select id="attendee-response" name="response">${['Going','Maybe','Declined','Waitlist'].map(r=>`<option ${a.response===r?'selected':''}>${r}</option>`).join('')}</select></div></div><p class="event-form-error" role="alert"></p><div class="dialog-actions">${btn('Back to attendees','event-detail-tab',`data-id="${e.id}" data-tab="attendees"`,'secondary')}<button type="submit" class="btn">Save RSVP</button></div></form>`);}
 function showPhoto(id,index){const e=eventById(id);if(!e?.photos.length)return;const i=(index+e.photos.length)%e.photos.length,p=e.photos[i];openDialog(esc(e.title),`Picture ${i+1} of ${e.photos.length} · ${esc(p.caption)}${p.illustrative?' · Illustrative sample venue':''}`,`<div class="event-lightbox"><img src="${esc(safePhotoUrl(p.url)||'')}" alt="${esc(p.caption)}" referrerpolicy="no-referrer"></div><div class="dialog-actions">${btn('← Previous','event-photo',`data-id="${id}" data-index="${i-1}" ${e.photos.length<2?'disabled':''}`,'secondary')}${btn('Next →','event-photo',`data-id="${id}" data-index="${i+1}" ${e.photos.length<2?'disabled':''}`,'secondary')}${btn('Back to pictures','event-detail-tab',`data-id="${id}" data-tab="photos"`)}</div>${btn('Remove this picture','event-photo-remove',`data-id="${id}" data-index="${i}"`,'ghost small')}`);}
 function exportEvents(){const rows=[['Event ID','Event','Properties','Date','Start ET','End ET','Type','Status','Location','Organizer','Capacity','Confirmed RSVPs incl guests','Attended incl guests','Waitlist incl guests','Photos'],...selection().map(e=>{const c=eventCounts(e);return[e.id,e.title,scopeName(e),e.date,e.start,e.end,e.type,eventStatus(e),e.location,e.owner,e.capacity,c.rsvps,c.attended,c.waitlist,e.photos.length];})];const csv=rows.map(r=>r.map(v=>{let s=String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='MF-Hub-events-'+activeTab+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Events exported for the current view and filters.');}
 function action(b){const {action,id}=b.dataset;if(!action.startsWith('event-'))return false;try{
 if(action==='event-open')details(id);
 else if(action==='event-new')eventForm();
 else if(action==='event-edit')eventForm(id);
 else if(action==='event-detail-tab')details(id,b.dataset.tab);
 else if(action==='event-clear'){Object.assign(filters,{property:'all',pmc:'all',city:'all'});filter={type:'all',from:'',to:'',search:''};render();}
 else if(action==='event-scope'){Object.assign(filters,{property:b.dataset.property,pmc:'all',city:'all'});filter={type:'all',from:'',to:'',search:''};navigate('events/planned');}
 else if(action==='event-month'){const [y,m]=month.split('-').map(Number),d=new Date(y,m-1+Number(b.dataset.step),1);month=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');render();}
 else if(action==='event-today'){month=today().slice(0,7);render();}
 else if(action==='event-cancel'){commit(()=>{const e=eventById(id);e.cancelled=!e.cancelled;});render();details(id);toast('Event status updated. No notifications sent.');}
 else if(action==='event-attendee-new')attendeeForm(id);
 else if(action==='event-attendee-edit')attendeeForm(id,b.dataset.person);
 else if(action==='event-checkin'){commit(()=>checkIn(eventById(id),b.dataset.person));render();details(id,'attendees');}
 else if(action==='event-photo')showPhoto(id,Number(b.dataset.index));
 else if(action==='event-photo-remove'){commit(()=>eventById(id).photos.splice(Number(b.dataset.index),1));render();details(id,'photos');}
 else if(action==='event-export')exportEvents();
 }catch(e){toast(e.message);}return true;}
 function change(el){if(el.dataset.eventScope){filters[el.dataset.eventScope]=el.value;render();return true;}if(el.dataset.eventFilter){const key=el.dataset.eventFilter,old=filter[key];filter[key]=el.value;if(filter.from&&filter.to&&filter.from>filter.to){filter[key]=old;el.value=old;toast('The end date must be on or after the start date.');return true;}if(key==='from'&&el.value)month=el.value.slice(0,7);render();return true;}if(el.id==='event-month'){if(el.value)month=el.value;render();return true;}return false;}
 function submit(event){const form=event.target;if(!['event-form','event-attendee-form','event-photo-form','event-search-form'].includes(form.id))return false;event.preventDefault();void (async()=>{try{const fields=new FormData(form);if(form.id==='event-search-form'){filter.search=String(fields.get('search')).trim();render();return;}
 if(form.id==='event-form'){const saved=commit(()=>saveEvent(data,{...Object.fromEntries(fields),propertyIds:fields.getAll('propertyIds')},form.dataset.id||undefined));month=saved.date.slice(0,7);render();details(saved.id);toast('Event saved in this browser.');}
 else if(form.id==='event-attendee-form'){commit(()=>saveAttendee(eventById(form.dataset.id),Object.fromEntries(fields),form.dataset.person||undefined));render();details(form.dataset.id,'attendees');toast('RSVP saved.');}
 else {const file=fields.get('file');if(!file?.size)throw Error('Select a picture first.');if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>1024*1024)throw Error('Choose a JPEG, PNG or WebP image no larger than 1 MB.');if(eventById(form.dataset.id).photos.length>=8)throw Error('This event already has 8 pictures. Remove one before adding another.');const save=form.querySelector('[type=submit]');save.disabled=true;const url=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('This picture could not be read.'));r.readAsDataURL(file);});if(!safePhotoUrl(url))throw Error('Unsupported image.');commit(()=>eventById(form.dataset.id).photos.push({id:crypto.randomUUID(),url,caption:String(fields.get('caption')).trim().slice(0,120),illustrative:false}));render();details(form.dataset.id,'photos');toast('Picture saved in this browser.');}
 }catch(e){const error=form.querySelector('.event-form-error');if(error)error.textContent=e.message;else toast(e.message);const save=form.querySelector('[type=submit]');if(save)save.disabled=false;}})();return true;}
 function reset(){commit(()=>{data=seedEvents();});filter={type:'all',from:'',to:'',search:''};month=today().slice(0,7);}
 return {workspace,summary,action,change,submit,reset};
}
